import { ACTIVITIES, BASE_ACTIVITIES, CATEGORIES, FEATURED_IDS, getBaseById, getActivityById, searchActivities, suggestActivity } from './catalog.mjs';
import { assessImpact, BASELINE, DOMAINS, domainSignals, goalProgress, insights, localDate, addDays, scoreTimeline, streak, trendSeries, clamp, ENGINE_VERSION } from './engine.mjs';
import { emptyState, loadState, saveState, exportData, importData, toCSV, STORE_KEY } from './storage.mjs';

const $=selector=>document.querySelector(selector);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>Number(x||0).toLocaleString('en-AU');
const uid=()=>globalThis.crypto?.randomUUID?.() || `id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const formatDate=x=>{try{return new Date(x).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'});}catch{return ''}};
const formatShort=x=>{try{return new Date(x).toLocaleDateString('en-AU',{day:'numeric',month:'short'});}catch{return ''}};
const today=()=>localDate(new Date());
const iconFor=domain=>({body:'◈',rest:'☾',mind:'◉',connection:'♡',purpose:'✦',environment:'❋'})[domain]||'✳';
const navigation=[['today','Overview','◫'],['log','Activity library','⊕'],['timeline','Life map','▦'],['mind','Mind & mood','◉'],['body','Body & rest','◈'],['insights','Intelligence','✧'],['goals','Goals & habits','◎'],['journal','Reflections','≋'],['reports','Reports','▤'],['settings','Settings','⚙']];
const pageTitles={today:['Your life, in perspective.','A clearer picture of your wellbeing, one choice at a time.'],log:['Activity library','Log an activity or describe your day in your own words.'],timeline:['Your life map','See the small moments and patterns that shape your weeks.'],mind:['Mind & mood','A space for your emotional wellbeing, without judgment.'],body:['Body & rest','A practical view of sleep, hydration, movement and daily rhythms.'],insights:['Your life intelligence','Pattern-based reflections using only the information you choose to record.'],goals:['Goals & habits','Build momentum around what matters to you.'],journal:['Reflections','Write, notice, and make meaning from everyday life.'],reports:['Reports & progress','Turn your activity history into an understandable picture.'],settings:['Your VitaLab','Your data, your preferences, your decisions.']};
let state=loadState();
let ui={tab:'today',category:'All',query:'',modal:null,selectedMood:3,selectedGoals:[],toastTimer:null,viewDate:new Date(),checkinMode:'full'};
const validTabs=new Set(navigation.map(x=>x[0]));
function save(){try{saveState(state)}catch(e){toast('Storage is full or unavailable. Export your data to preserve it.')}}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(ui.toastTimer);ui.toastTimer=setTimeout(()=>el.classList.remove('show'),3900)}
function download(content,filename,mime='text/plain'){const blob=new Blob([content],{type:mime});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function navigate(tab){if(!validTabs.has(tab))tab='today';ui.tab=tab;location.hash=`/${tab}`;render();window.scrollTo({top:0,behavior:'instant'})}
function computed(){const now=new Date();const score=scoreTimeline(state.logs,now);const series=trendSeries(state.logs,14,now);const last=state.logs.filter(l=>new Date(l.loggedAt).getTime()>=now.getTime()-7*86400000);return {score,series,last,domains:domainSignals(state.logs,14,now),checkin:state.checkins.find(c=>c.date===today()),streak:streak(state.logs,now)};}
function heroCard(x){const change=x.series.length>7?x.score.score-x.series[x.series.length-8].score:0;const diff=change>0?`+${change}`:String(change);const pct=Math.round(x.score.score/10);return `<section class="hero-card" aria-label="LifeScore overview"><div class="hero-copy"><div class="eyebrow">Your LifeScore™</div><h2>Every choice is part of the bigger picture.</h2><p>A transparent reflection of recent, logged behaviours across your life. Not a diagnosis or a measure of your worth.</p><div class="row" style="gap:10px;flex-wrap:wrap"><button class="button primary" data-nav="log">⊕ &nbsp; Log an activity</button><span class="chip good">${diff} this week</span></div></div><div class="score-visual"><div class="score-ring" style="--scorepct:${pct}%"></div><div class="score-inner"><div class="score-value mono">${x.score.score}</div><div class="score-denom">out of 1,000</div><div class="score-caption">LifeScore</div></div></div></section>`}
function chart(series,short=false){if(!series?.length)return `<div class="empty-mini">No entries to chart yet.</div>`;const w=640,h=155,p=23,ys=series.map(x=>x.score),min=Math.max(0,Math.min(...ys)-25),max=Math.min(1000,Math.max(...ys)+25),span=Math.max(1,max-min);const xy=series.map((s,i)=>({x:p+(i/(series.length-1||1))*(w-p*2),y:h-p-((s.score-min)/span)*(h-p*2)}));const line=xy.map((v,i)=>`${i?'L':'M'}${v.x.toFixed(1)},${v.y.toFixed(1)}`).join(' ');const area=`${line} L${xy[xy.length-1].x},${h-p} L${xy[0].x},${h-p} Z`;const marks=short?[0,Math.floor((series.length-1)/2),series.length-1]:[0,Math.floor((series.length-1)/3),Math.floor((series.length-1)*2/3),series.length-1];return `<svg class="sparkline" viewBox="0 0 ${w} ${h}" role="img" aria-label="LifeScore trend from ${formatShort(series[0].date)} to ${formatShort(series[series.length-1].date)}; latest score ${ys[ys.length-1]}"><defs><linearGradient id="scoreFade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--mint)" stop-opacity=".25"/><stop offset="1" stop-color="var(--mint)" stop-opacity="0"/></linearGradient></defs>${[.2,.5,.8].map(t=>`<line class="chart-gridline" x1="${p}" y1="${p+(h-p*2)*t}" x2="${w-p}" y2="${p+(h-p*2)*t}" />`).join('')}<path d="${area}" fill="url(#scoreFade)"/><path class="chart-line" d="${line}"/><circle class="chart-dot" cx="${xy[xy.length-1].x}" cy="${xy[xy.length-1].y}" r="5"/>${[...new Set(marks)].map(i=>`<text class="chart-label" x="${xy[i].x}" y="${h-3}" text-anchor="middle">${formatShort(series[i].date)}</text>`).join('')}</svg>`}
function recentRows(logs,limit=6){const list=[...logs].sort((a,b)=>new Date(b.loggedAt)-new Date(a.loggedAt)).slice(0,limit);if(!list.length)return emptyBlock('✳','Nothing logged yet','Your activities will appear here when you add your first entry.');return list.map(l=>`<div class="activity-row"><div class="activity-glyph" aria-hidden="true">${iconFor(l.domain)}</div><div class="activity-info"><strong title="${esc(l.title)}">${esc(l.title)}</strong><small>${esc(l.category||l.domain)} · ${formatDate(l.loggedAt)} · ${num(l.duration||0)} min</small></div><span class="delta ${l.impact<0?'negative':''}" aria-label="Score impact ${l.impact}">${l.impact>0?'+':''}${l.impact}</span><button class="button ghost small icon-only" data-action="delete-log" data-id="${esc(l.id)}" aria-label="Delete ${esc(l.title)}">×</button></div>`).join('')}
function emptyBlock(symbol,title,text){return `<div class="empty"><span class="big" aria-hidden="true">${symbol}</span><strong>${esc(title)}</strong><span class="small">${esc(text)}</span></div>`}
function kpi(label,value,subtitle,symbol='✧'){return `<div class="card"><div class="row-between"><span class="panel-label">${label}</span><span class="tile-icon" aria-hidden="true">${symbol}</span></div><div class="kpi">${value}</div><div class="kpi-caption">${subtitle}</div></div>`}
function domainsBlock(x){const max=Math.max(1,...x.domains.map(d=>d.count));return x.domains.map(d=>`<div class="domain-row"><span class="domain-name">${d.name}</span><div class="domain-bar" title="${d.count} entries"><div class="domain-fill" style="width:${d.count/max*100}%;background:${d.color}"></div></div><span class="domain-count mono">${d.count} logs</span></div>`).join('')}
function quickActions(){return FEATURED_IDS.map(id=>{const b=getBaseById(id);if(!b)return '';return `<button class="quick-action" data-action="quick" data-id="${id}"><span class="quick-icon" aria-hidden="true">${iconFor(b.domain)}</span><span class="quick-label">${esc(b.name)}</span></button>`}).join('')}
function rating(name,value,labels=[]){return `<div class="rating" role="group" aria-label="${esc(name)}">${[1,2,3,4,5].map(n=>`<button type="button" class="${n===Number(value)?'selected':''}" data-action="rate" data-name="${name}" data-value="${n}" aria-pressed="${n===Number(value)}" title="${esc(labels[n-1]||String(n))}">${n}</button>`).join('')}</div><input type="hidden" name="${name}" value="${value}">`}
function checkinForm(compact=false){const c=state.checkins.find(x=>x.date===today());return `<form id="checkin-form" class="stack"><div class="row-between"><div><h3 class="mb0">Today's pulse</h3><p class="card-subtitle">How are you, really?</p></div><span class="chip ${c?'good':''}">${c?'✓ Saved today':'~ 30 seconds'}</span></div><label class="field">Mood <span class="field-caption">1 = low, 5 = great. All feelings are welcome.</span>${rating('mood',c?.mood??3)}</label><label class="field">Energy <span class="field-caption">1 = depleted, 5 = energised</span>${rating('energy',c?.energy??3)}</label>${compact?'':`<label class="field">Stress <span class="field-caption">1 = calm, 5 = intense</span>${rating('stress',c?.stress??3)}</label><div class="form-grid"><label class="field">Sleep last night (hours)<input name="sleepHours" class="input" type="number" min="0" max="24" step=".25" placeholder="e.g. 7.5" value="${esc(c?.sleepHours??'')}"></label><label class="field">Water (glasses)<input name="waterGlasses" class="input" type="number" min="0" max="40" step="1" placeholder="e.g. 6" value="${esc(c?.waterGlasses??'')}"></label><label class="field">Steps (optional)<input name="steps" class="input" type="number" min="0" max="100000" step="1" placeholder="e.g. 6500" value="${esc(c?.steps??'')}"></label><label class="field">Resting heart rate (optional)<input name="restingHr" class="input" type="number" min="20" max="240" placeholder="bpm" value="${esc(c?.restingHr??'')}"></label></div><label class="field">A thought to remember (optional)<textarea class="textarea" name="notes" maxlength="2000" rows="2" placeholder="What might be affecting your day?">${esc(c?.notes??'')}</textarea></label>`}<button class="button primary w100" type="submit">${c?'Update check-in':'Save today\'s check-in'} ↗</button><div class="score-note"><i>ⓘ</i> Mood, stress and other symptoms do not reduce your LifeScore. It only reflects chosen, logged behaviours.</div></form>`}
function renderToday(x){const recent=x.last.length,counts=new Set(state.logs.map(l=>localDate(l.loggedAt))).size;return `<div class="stack-lg">${heroCard(x)}<div class="grid four">${kpi('Activities this week',num(recent),'Entries in the last 7 days','↗')}${kpi('Logging streak',`${x.streak} ${x.streak===1?'day':'days'}`,'No penalty for missing a day','◎')}${kpi('Days tracked',num(counts),'Since you began logging','◷')}${kpi('Daily check-in',x.checkin?'Done':'Not yet',x.checkin?'Thanks for checking in':'Capture how today feels','♡')}</div><div class="grid main"><div class="stack-lg"><section class="card"><div class="card-head"><div><h2>LifeScore trajectory</h2><div class="card-subtitle">Last 14 days · consistent, versioned calculations</div></div><span class="chip good">0–1,000</span></div>${chart(x.series)}<div class="legend-row"><span><i class="dot"></i> LifeScore</span><span>Baseline ${BASELINE} · rolling 35-day signals</span></div></section><section class="card"><div class="card-head"><div><h2>Life dimensions</h2><div class="card-subtitle">What you've logged over the last 14 days</div></div><button class="button small ghost" data-nav="insights">Explore ↗</button></div>${domainsBlock(x)}<p class="score-note"><i>ⓘ</i> More entries in a domain means more tracking, not necessarily better health.</p></section><section class="card"><div class="card-head"><div><h2>Recently logged</h2><div class="card-subtitle">The moments you chose to capture</div></div><button class="button small ghost" data-nav="timeline">See all ↗</button></div>${recentRows(state.logs,5)}</section></div><aside class="stack-lg"><section class="card">${checkinForm(true)}</section><section class="card"><div class="card-head"><div><h2>Quick log</h2><div class="card-subtitle">Your everyday essentials</div></div></div><div class="quick-grid">${quickActions()}</div><button data-nav="log" class="button ghost w100 mt20">Browse ${num(ACTIVITIES.length)} options ↗</button></section><section class="card soft"><span class="eyebrow">A gentle insight</span><div class="insight" style="border:0;padding-bottom:0"><div class="insight-symbol">✧</div><div><strong>${esc(insights(state.logs,state.checkins)[0].title)}</strong><p>${esc(insights(state.logs,state.checkins)[0].body)}</p></div></div><button class="button small ghost mt10" data-nav="insights">More insights ↗</button></section></aside></div></div>`}
function catalogCards(items){if(!items.length)return emptyBlock('⌕','No matching activities','Try a shorter phrase or switch to another category.');return `<div class="catalog-list">${items.map(a=>`<button class="catalog-item" data-action="select-activity" data-id="${a.id}"><span class="activity-glyph" aria-hidden="true">${iconFor(a.domain)}</span><span class="flex1"><strong>${esc(a.title)}</strong><small>${esc(a.category)} · ${esc(a.label)}</small></span><span class="end">${a.baseImpact>0?'+':''}${a.baseImpact} base<br><small>Log ↗</small></span></button>`).join('')}</div>`}
function renderLog(){const results=searchActivities(ui.query,ui.category,42);const suggestions=ui.query.length>2?suggestActivity(ui.query).slice(0,4):[];return `<div class="stack-lg"><section class="card"><div class="eyebrow">Write it naturally</div><h2 style="margin:9px 0">What did you do today?</h2><p class="muted small">Describe an activity in plain language. VitaLab suggests existing matches without inventing a score.</p><div class="row" style="align-items:stretch"><input id="natural-input" class="input" aria-label="Describe your activity" placeholder="e.g. Went to the gym for 40 minutes" style="flex:1" maxlength="280"><button class="button primary" data-action="suggest-natural">Find matches ↗</button></div><div id="natural-results" class="mt10"></div></section><section class="card"><div class="card-head"><div><h2>Browse the activity library</h2><div class="card-subtitle">${num(BASE_ACTIVITIES.length)} core activities · ${num(ACTIVITIES.length)} contextual choices</div></div><span class="chip good">Versioned weights</span></div><div class="search-line"><div class="search-box"><span class="search-icon">⌕</span><input id="catalog-search" class="input" type="search" placeholder="Search walking, yoga, sleep, relationships, slang..." value="${esc(ui.query)}" autocomplete="off" aria-label="Search activities"></div><select id="catalog-category" aria-label="Choose activity category" class="select"><option value="All">All categories</option>${CATEGORIES.map(c=>`<option value="${esc(c)}" ${ui.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="result-count" id="catalog-count">${results.length} base activities shown. Select one to choose a specific variant.</div><div id="catalog-results">${catalogCards(results)}</div><p class="score-note"><i>ⓘ</i> Activity impact is defined by the VitaLab algorithm, not an editable user score. Context, duration and intensity affect the final estimate.</p></section></div>`}
function refreshCatalog(){const items=searchActivities(ui.query,ui.category,42),panel=$('#catalog-results'),count=$('#catalog-count');if(panel)panel.innerHTML=catalogCards(items);if(count)count.textContent=`${items.length} base activities shown. Select one to choose a specific variant.`;}
function renderCalendar(){const date=new Date(ui.viewDate),month=date.getMonth(),year=date.getFullYear(),start=new Date(year,month,1),last=new Date(year,month+1,0).getDate(),dayOffset=(start.getDay()+6)%7,logCounts=new Map();state.logs.forEach(l=>logCounts.set(localDate(l.loggedAt),(logCounts.get(localDate(l.loggedAt))||0)+1));const cells=[];for(let i=0;i<dayOffset;i++)cells.push('<div aria-hidden="true"></div>');for(let n=1;n<=last;n++){const key=localDate(new Date(year,month,n)),count=logCounts.get(key)||0;cells.push(`<div class="day-cell ${count?'filled':''} ${key===today()?'today':''}" title="${key}: ${count} logs"><span>${n}</span>${count?'<span class="day-dot"></span>':'<span style="height:5px"></span>'}</div>`)}return `<div class="row-between mb20"><button class="button small ghost" data-action="prev-month" aria-label="Previous month">‹</button><strong>${date.toLocaleDateString('en-AU',{month:'long',year:'numeric'})}</strong><button class="button small ghost" data-action="next-month" aria-label="Next month">›</button></div><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(x=>`<div class="calendar-label">${x}</div>`).join('')}${cells.join('')}</div>`}
function renderTimeline(){return `<div class="grid main"><div class="stack-lg"><section class="card"><div class="card-head"><div><h2>Activity history</h2><div class="card-subtitle">Your journey, in chronological order</div></div><button class="button primary small" data-nav="log">+ Add activity</button></div>${recentRows(state.logs,100)}</section></div><aside class="stack-lg"><section class="card"><div class="card-head"><h2>Activity calendar</h2></div>${renderCalendar()}</section><section class="card"><h2>What counts?</h2><p class="muted small">Every logged activity appears here. Your LifeScore gives more recent choices greater weight, uses diminishing returns for duplicates and limits daily point stacking.</p><button class="button ghost small" data-nav="reports">How the score works ↗</button></section></aside></div>`}
function renderMind(){const recent=state.checkins.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);const avg=recent.length?(recent.reduce((n,c)=>n+Number(c.mood||0),0)/recent.length).toFixed(1):'—';return `<div class="grid main-balanced"><div class="stack-lg"><section class="card">${checkinForm(false)}</section><section class="card"><div class="card-head"><div><h2>Check-in history</h2><div class="card-subtitle">Feelings are data, not grades</div></div></div>${recent.length?recent.map(c=>`<div class="activity-row"><span class="activity-glyph">♡</span><div class="activity-info"><strong>${formatDate(c.date)}</strong><small>Mood ${c.mood||'—'}/5 · Energy ${c.energy||'—'}/5 · Stress ${c.stress||'—'}/5</small></div>${c.notes?`<span class="chip">With note</span>`:''}</div>`).join(''):emptyBlock('♡','No check-ins yet','Check in whenever it feels useful.')}</section></div><aside class="stack-lg"><section class="card"><span class="eyebrow">Mood overview</span><div class="kpi">${avg}<span class="small muted"> / 5</span></div><p class="kpi-caption">Average of up to eight recent check-ins</p><div class="divider"></div><p class="muted small">A low mood never counts as negative behaviour. VitaLab can help you notice how circumstances relate to mood, but it cannot diagnose mental health conditions.</p></section><section class="card soft"><h2>Gentle reflection</h2><p class="muted small">What felt energising today? What felt difficult? What did you need more of?</p><button class="button primary" data-nav="journal">Write a reflection ↗</button></section></aside></div>`}
function renderBody(){const x=computed();const recent=state.checkins.filter(c=>c.date>=localDate(addDays(new Date(),-14)));const sleep=recent.filter(c=>c.sleepHours!=='' && c.sleepHours!=null),water=recent.filter(c=>c.waterGlasses!=='' && c.waterGlasses!=null);const avg=(arr,key)=>arr.length?(arr.reduce((n,c)=>n+Number(c[key]),0)/arr.length).toFixed(1):'—';const top=state.logs.filter(l=>l.domain==='body'||l.domain==='rest').sort((a,b)=>new Date(b.loggedAt)-new Date(a.loggedAt));return `<div class="stack-lg"><div class="grid three">${kpi('Reported sleep',sleep.length?avg(sleep,'sleepHours')+' h':'—',`${sleep.length} check-ins in 14 days`,'☾')}${kpi('Reported water',water.length?avg(water,'waterGlasses'):'—',`Glasses per tracked day`,'◈')}${kpi('Body & rest logs',top.length,`Manually logged signals`,'↗')}</div><div class="grid main-balanced"><section class="card"><div class="card-head"><div><h2>Your body, your rhythm</h2><div class="card-subtitle">Sleep, movement and nourishment over time</div></div><button class="button primary small" data-nav="log">Log an activity</button></div>${top.length?recentRows(top,18):emptyBlock('☾','No body or rest entries yet','Try logging a walk, a restorative break or an activity that mattered to you.')}</section><aside class="stack-lg"><section class="card"><h2>Manual measurements</h2><p class="muted small">For now, enter sleep, water, steps and resting heart rate in your daily check-in. Wearable connectors are not active in this local build.</p><button class="button ghost w100" data-nav="mind">Open daily check-in ↗</button></section><section class="card soft"><h2>Health data boundaries</h2><p class="muted small">VitaLab does not diagnose conditions, rate bodies, or change your score based on weight, disability, symptoms or personal identity. Consult an appropriate clinician for medical concerns.</p></section></aside></div></div>`}
function insightCard(ins){const symbol={welcome:'✳',checkin:'♡',pattern:'↗',balance:'◎',sleep:'☾',mood:'◉',domain:'◈',steady:'✧'}[ins.kind]||'✧';return `<div class="insight"><div class="insight-symbol">${symbol}</div><div><strong>${esc(ins.title)}</strong><p>${esc(ins.body)}</p><small>${esc(ins.confidence)}</small></div></div>`}
function renderInsights(x){const items=insights(state.logs,state.checkins);return `<div class="grid main-balanced"><div class="stack-lg"><section class="card"><div class="card-head"><div><h2>What your data is saying</h2><p class="card-subtitle">Conservative, explainable observations</p></div><span class="chip good">Based on your entries</span></div>${items.map(insightCard).join('')}</section><section class="card"><h2>Areas you've explored</h2><p class="card-subtitle">Activity distribution · last 14 days</p>${domainsBlock(x)}</section></div><aside class="stack-lg"><section class="card soft"><span class="eyebrow">How insights work</span><h2 style="margin-top:11px">Curious, not clinical.</h2><p class="muted small">These insights use deterministic calculations and simple pattern rules. This build does not send your journal or health details to an AI model or external server.</p><p class="muted small">Future AI reflections can be added behind explicit consent and human-friendly explanations.</p></section><section class="card"><h2>More context = better reflections</h2><p class="muted small">Add a few check-ins and activities across your week. Missing entries are treated as unknown, not unhealthy.</p><button class="button primary" data-nav="log">Add an activity ↗</button></section></aside></div>`}
function renderGoals(){return `<div class="stack-lg"><div class="grid main-balanced"><section class="card"><div class="card-head"><div><h2>Your active goals</h2><p class="card-subtitle">Weekly, flexible targets with no missed-day penalties</p></div></div>${state.goals.length?`<div class="grid two">${state.goals.map(g=>{const p=goalProgress(g,state.logs);return `<div class="card soft goal-card"><div class="goal-top"><div class="goal-symbol">${iconFor(g.domain)}</div><div class="flex1"><strong>${esc(g.title)}</strong><div class="small muted">${esc(DOMAINS.find(d=>d.id===g.domain)?.name||g.domain)}</div></div><button class="button small ghost icon-only" data-action="delete-goal" data-id="${esc(g.id)}" aria-label="Remove goal">×</button></div><div class="goal-progress"><span>${p.completed} of ${p.target} this week</span><strong>${p.percent}%</strong></div><div class="progress-track"><div class="progress-fill" style="width:${p.percent}%"></div></div></div>`}).join('')}</div>`:emptyBlock('◎','No goals yet','Set one small, meaningful goal to make your progress visible.')}</section><aside class="card"><h2>Create a goal</h2><p class="card-subtitle">A gentle target, not another obligation</p><form id="goal-form" class="stack mt20"><label class="field">Goal name<input name="title" class="input" required maxlength="90" placeholder="e.g. Make time for movement"></label><label class="field">Life dimension<select name="domain" class="select">${DOMAINS.map(d=>`<option value="${d.id}">${d.name}</option>`).join('')}</select></label><label class="field">Entries per week<input name="target" class="input" type="number" min="1" max="28" value="3" required></label><button type="submit" class="button primary w100">Create goal ↗</button></form></aside></div><section class="card soft"><span class="eyebrow">Personal challenges</span><h2 style="margin-top:8px">Small actions, meaningful momentum.</h2><p class="muted small">A challenge is simply a goal you choose for yourself. Social leaderboards and public sharing are intentionally off in this private build.</p></section></div>`}
function renderJournal(){const entries=[...state.journal].sort((a,b)=>new Date(b.at)-new Date(a.at));return `<div class="grid main-balanced"><section class="card"><h2>Take a moment</h2><p class="muted small">Your private reflections add context to the story your numbers cannot tell.</p><form id="journal-form" class="stack"><label class="field">What's on your mind?<textarea name="text" class="textarea" maxlength="4000" rows="8" required placeholder="Today I noticed...\nSomething I want to remember...\nOne thing I could do for myself... "></textarea></label><button type="submit" class="button primary">Save private reflection ↗</button></form><div class="note-box mt20">Stored locally in this browser. It is not encrypted or synced. Export and delete controls are in Settings; avoid shared devices for sensitive entries.</div></section><aside class="card"><div class="card-head"><h2>Earlier reflections</h2><span class="chip">${entries.length}</span></div>${entries.length?entries.slice(0,20).map(j=>`<div class="journal-entry"><div class="row-between"><span class="journal-date">${formatDate(j.at)}</span><button data-action="delete-journal" data-id="${esc(j.id)}" class="button small ghost" aria-label="Delete reflection">Delete</button></div><p>${esc(j.text)}</p></div>`).join(''):emptyBlock('≋','A fresh page','This space is yours to fill, whenever you like.')}</aside></div>`}
function renderReports(x){const week=x.last,series30=trendSeries(state.logs,30);const positives=week.filter(l=>l.impact>0).length,negatives=week.filter(l=>l.impact<0).length;return `<div class="stack-lg"><div class="grid four">${kpi('Current LifeScore',x.score.score,'A behavioural reflection index','✳')}${kpi('7-day entries',week.length,'All recent activities','↗')}${kpi('Positive signals',positives,'Logged this week','+')}${kpi('Other signals',negatives,'Logged this week','−')}</div><section class="card"><div class="card-head"><div><h2>30-day LifeScore trend</h2><p class="card-subtitle">Rolling recent behaviours with decay and repeat limits</p></div><span class="chip">0–1,000</span></div>${chart(series30)}<div class="legend-row"><span>Scores recalculate deterministically from your logs</span><span>Engine ${ENGINE_VERSION}</span></div></section><div class="grid main-balanced"><section class="card"><h2>The LifeScore methodology</h2><p class="muted small">VitaLab starts at a neutral baseline of 500. Each logged activity has a fixed, reviewed base weight. Duration and intensity adjust the effect within bounds; identical activities have diminishing returns, and each day's contributions are capped. Older entries fade gradually over 35 days. The final result is clamped between 0 and 1,000.</p><div class="divider"></div><div class="grid two"><div class="report-metric"><div class="label">Baseline</div><div class="value">500</div></div><div class="report-metric"><div class="label">Recency half-life</div><div class="value">10 days</div></div><div class="report-metric"><div class="label">Daily positive cap</div><div class="value">+65</div></div><div class="report-metric"><div class="label">Daily negative cap</div><div class="value">−65</div></div></div><div class="note-box mt20"><strong>Important:</strong> LifeScore is an experimental, user-facing tracking metric. It is not a validated clinical wellness score and cannot predict disease, mental health outcomes, or risk of harm.</div></section><aside class="stack-lg"><section class="card"><h2>Take your data with you</h2><p class="muted small">Download your activity history as CSV, or take a complete JSON backup containing your profile, check-ins, goals and reflections.</p><div class="stack"><button class="button primary" data-action="export-json">↓ Export complete data</button><button class="button ghost" data-action="export-csv">↓ Download activities CSV</button><button class="button ghost" data-action="print">▤ Print this report</button></div></section><section class="card soft"><h2>Data quality</h2><p class="muted small">${state.logs.length} activity entries and ${state.checkins.length} check-ins recorded. Activity categories are not clinical domains, and personal logging frequency should not be confused with health status.</p></section></aside></div></div>`}
function renderSettings(){return `<div class="grid main-balanced"><div class="stack-lg"><section class="card"><h2>Your preferences</h2><form id="settings-form" class="stack mt20"><label class="field">Display name<input class="input" name="name" maxlength="70" value="${esc(state.profile.name)}" placeholder="Name (optional)"></label><label class="field">Appearance<select name="theme" class="select"><option value="dark" ${state.profile.theme==='dark'?'selected':''}>Obsidian mineral · dark</option><option value="light" ${state.profile.theme==='light'?'selected':''}>Soft mineral · light</option></select></label><button class="button primary" type="submit">Save preferences</button></form></section><section class="card"><h2>Data ownership</h2><p class="muted small">This beta saves entries in this browser's local storage. It does not create an online account, encrypt stored data, sync to the cloud or connect wearables. Clear browser data or switch devices and these records may disappear without an export.</p><div class="form-actions"><button class="button" data-action="export-json">↓ Download backup</button><button class="button" data-action="export-csv">↓ Export CSV</button></div><div class="divider"></div><label class="field">Restore a VitaLab V3 JSON backup<input class="input" id="import-file" type="file" accept="application/json,.json"></label><p class="field-caption mt10">Import replaces this workspace after you confirm. Review the source of the file before importing.</p></section><section class="card"><h2>Danger zone</h2><p class="muted small">Remove all saved activity logs, journal entries and check-ins from this browser. This cannot be undone without a backup.</p><button class="button danger" data-action="clear-all">Delete all local data</button></section></div><aside class="stack-lg"><section class="card soft"><span class="eyebrow">VitaLab 3.0</span><h2 style="margin-top:8px">Built around the whole of life.</h2><p class="muted small">Holistic activity logging, emotion context, sleep, nutrition, self-care, environment, connections, goals, life intelligence and data portability.</p><div class="divider"></div><div class="row-between"><span class="small muted">Scoring engine</span><strong class="small">${ENGINE_VERSION}</strong></div><div class="row-between mt10"><span class="small muted">Activity options</span><strong class="small">${num(ACTIVITIES.length)}</strong></div><div class="row-between mt10"><span class="small muted">Workspace</span><strong class="small">${state.demo?'Demo data':'Local device'}</strong></div></section><section class="card"><h2>Integrations status</h2><div class="activity-row"><span class="activity-glyph">◈</span><div class="activity-info"><strong>Apple Health / Health Connect</strong><small>Not connected</small></div><span class="chip">Planned</span></div><div class="activity-row"><span class="activity-glyph">☁</span><div class="activity-info"><strong>Cloud account & synchronisation</strong><small>Not configured</small></div><span class="chip">Planned</span></div><div class="activity-row"><span class="activity-glyph">✧</span><div class="activity-info"><strong>LLM reflection companion</strong><small>Not enabled. Pattern insights work locally.</small></div><span class="chip">Planned</span></div></section></aside></div>`}
function renderOnboarding(){const choices=['Better sleep','More energy','Manage stress','Move more','Mindful routines','More connection','Find balance','Personal growth'];return `<div class="onboard-wrap"><div class="onboard"><div class="onboard-art"><div class="logo-lockup" style="color:#f0f9ec"><span class="brand-mark">✳</span> vitalab <span style="font-size:10px;opacity:.7;letter-spacing:0">3.0</span></div><div><div class="eyebrow" style="color:#bbebc9">A new perspective on wellbeing</div><h1 style="margin-top:15px">Your life is more than a number.</h1><p>Track the everyday choices, little breakthroughs and changing rhythms that make your story yours.</p></div><div class="onboard-wheel" aria-hidden="true">✳</div><span class="small" style="color:#b4d3bc">A private, local-first workspace</span></div><div class="onboard-form"><span class="eyebrow">Welcome to VitaLab</span><h2 style="font-size:31px;margin:11px 0">Let's make this yours.</h2><p class="muted small">No account required for this working beta. Your entries stay on this device unless you export them.</p><form id="onboard-form" class="stack mt20"><label class="field">What should we call you? (optional)<input class="input" name="name" maxlength="70" placeholder="Your first name"></label><div><label class="field">What would you like to focus on? (optional)</label><div class="row mt10" style="gap:8px;flex-wrap:wrap">${choices.map(c=>`<button type="button" class="goal-choice ${ui.selectedGoals.includes(c)?'selected':''}" data-action="toggle-onboard-goal" data-goal="${esc(c)}" aria-pressed="${ui.selectedGoals.includes(c)}">${esc(c)}</button>`).join('')}</div></div><div class="note-box">VitaLab does not measure your worth or provide medical advice. LifeScore is an experimental behavioural reflection index, not a diagnosis.</div><button class="button primary w100" type="submit">Create my VitaLab ↗</button></form><div class="row mt20"><div class="flex1" style="height:1px;background:var(--line)"></div><span class="small muted">or explore first</span><div class="flex1" style="height:1px;background:var(--line)"></div></div><button class="button ghost w100 mt10" data-action="launch-demo">Explore with clearly labelled sample data</button></div></div></div>`}
function renderModal(){if(!ui.modal)return '';if(ui.modal.type!=='activity')return '';const a=getActivityById(ui.modal.id),b=a&&getBaseById(a.baseId);if(!a||!b)return '';const variants=ACTIVITIES.filter(x=>x.baseId===b.id);const impact=assessImpact(a,{duration:ui.modal.duration??a.duration,intensity:ui.modal.intensity??a.intensity});return `<div class="modal-backdrop" id="modal-backdrop"><div class="modal-dialog" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="row-between"><span class="eyebrow">Log activity</span><button class="modal-close" data-action="close-modal" aria-label="Close dialog">×</button></div><h2 id="modal-title">${esc(b.name)}</h2><p class="modal-description">${esc(b.category)} · ${esc(DOMAINS.find(x=>x.id===b.domain)?.name||b.domain)}</p><form id="activity-form" class="stack"><label class="field">Select a context / variation<select id="activity-variant" name="variant" class="select">${variants.map(v=>`<option value="${v.id}" ${v.id===a.id?'selected':''}>${esc(v.label)}</option>`).join('')}</select></label><div class="form-grid"><label class="field">Duration (minutes)<input class="input" id="log-duration" name="duration" type="number" min="1" max="1440" required value="${impact.duration}"></label><label class="field">Intensity (${impact.intensity}/10)<input class="range" id="log-intensity" name="intensity" type="range" min="1" max="10" value="${impact.intensity}"><span class="field-caption">Light ↔ intense</span></label></div><label class="field">Note (optional)<textarea class="textarea" name="notes" maxlength="1500" rows="2" placeholder="What would you like to remember?"></textarea></label><div class="preview-impact"><div><strong class="small">Estimated LifeScore impact</strong><div class="field-caption">Weight × duration × intensity, with repeat limits on the score</div></div><span id="impact-preview" class="impact-number ${impact.impact<0?'negative':''}">${impact.impact>0?'+':''}${impact.impact}</span></div><button class="button primary w100" type="submit">Save activity ↗</button><div class="score-note"><i>ⓘ</i> Weights are set by the algorithm. Scores are an experimental reflection aid, not medical evidence.</div></form></div></div>`}
function render(){document.documentElement.dataset.theme=state.profile.theme||'dark';const app=$('#app');if(!state.profile.onboarded){app.innerHTML=renderOnboarding();return;}ui.tab=validTabs.has(location.hash.slice(2))?location.hash.slice(2):ui.tab;const x=computed(),name=state.profile.name?.trim();const date=new Date().toLocaleDateString('en-AU',{weekday:'long',day:'numeric',month:'long'});const navHtml=navigation.map(([id,title,sym])=>`<button class="nav-link ${ui.tab===id?'active':''}" data-nav="${id}" ${ui.tab===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${sym}</span>${title}</button>`).join('');const sections={today:()=>renderToday(x),log:renderLog,timeline:renderTimeline,mind:renderMind,body:renderBody,insights:()=>renderInsights(x),goals:renderGoals,journal:renderJournal,reports:()=>renderReports(x),settings:renderSettings};const heading=pageTitles[ui.tab]||pageTitles.today;app.innerHTML=`<div class="shell"><aside class="sidebar" aria-label="Primary navigation"><div class="brand"><span class="brand-mark">✳</span><div>vitalab<span class="brand-suffix">LIFE, IN PERSPECTIVE</span></div></div><div class="side-caption">YOUR SPACE</div><nav class="nav-stack">${navHtml.slice(0,0)}${navigation.slice(0,6).map(([id,title,sym])=>`<button class="nav-link ${ui.tab===id?'active':''}" data-nav="${id}" ${ui.tab===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${sym}</span>${title}</button>`).join('')}</nav><div class="side-caption">KEEP GROWING</div><nav class="nav-stack">${navigation.slice(6).map(([id,title,sym])=>`<button class="nav-link ${ui.tab===id?'active':''}" data-nav="${id}" ${ui.tab===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${sym}</span>${title}</button>`).join('')}</nav><div class="sidebar-foot"><div class="privacy-indicator"><div class="row" style="gap:7px;margin-bottom:6px"><span style="color:var(--mint)">●</span><b>Local-first beta</b></div>Your data stays in this browser. It is not encrypted or cloud-synced.</div><div class="row mt20"><div class="side-avatar">${esc((name||'V')[0].toUpperCase())}</div><div class="flex1"><strong class="small">${esc(name||'Your workspace')}</strong><div class="xsmall muted">${state.demo?'Sample data':'Private local workspace'}</div></div><button data-nav="settings" class="button ghost small icon-only" aria-label="Settings">⚙</button></div></div></aside><div class="content-shell"><header class="topbar"><div class="topbar-left"><div class="mobile-brand"><span class="brand-mark">✳</span> vitalab</div><div><div class="top-greeting">${esc(name?`Good to see you, ${name}`:'Welcome back')}</div><div class="today-date">${esc(date)}</div></div></div><div class="topbar-right">${state.demo?'<span class="capsule demo">● Demo workspace</span>':'<span class="capsule">● Stored locally</span>'}<button class="button ghost small" data-action="toggle-theme" aria-label="Toggle appearance"><span>${state.profile.theme==='light'?'☾':'☼'}</span> Theme</button><button class="button primary small" data-nav="log"><span>+</span> Log activity</button></div></header><main id="main" class="page-main" tabindex="-1"><div class="page-heading"><span class="eyebrow">VITALAB / ${ui.tab.toUpperCase()}</span><h1 style="margin-top:10px">${heading[0]}</h1><p>${heading[1]}</p></div>${sections[ui.tab]()}</main></div><nav class="mobile-nav" aria-label="Mobile navigation">${[['today','Home','◫'],['log','Log','⊕'],['timeline','Map','▦'],['insights','Insights','✧'],['settings','More','☷']].map(([id,title,sym])=>`<button data-nav="${id}" class="${ui.tab===id?'active':''}" aria-label="${title}" ${ui.tab===id?'aria-current="page"':''}><span class="icon">${sym}</span>${title}</button>`).join('')}</nav>${renderModal()}</div>`;if(ui.modal){const m=$('#modal-backdrop .modal-dialog');m?.querySelector('button')?.focus()}}
function demoData(){const data=emptyState();data.profile={name:'Explorer',goals:['Better sleep','Move more'],onboarded:true,theme:state.profile.theme||'dark'};data.demo=true;const ids=['went-for-a-walk','mindful-breathing','eating-a-balanced-lunch','catching-up-with-a-friend','focused-work-session','going-to-bed-on-time','drinking-a-glass-of-water','gentle-stretching','reading-a-book','journaling-about-feelings','cycling-outdoors','doomscrolling','gardening','planning-the-day','listening-to-music','yoga-flow'];for(let i=13;i>=0;i--){const date=addDays(new Date(),-i);date.setHours(i===0?Math.max(0,new Date().getHours()-1):8+(i%8),20,0,0);for(let j=0;j<(i%3===0?1:2);j++){const b=getBaseById(ids[(i*3+j)%ids.length]);if(!b)continue;const a=ACTIVITIES.find(a=>a.baseId===b.id);data.logs.push({id:uid(),activityId:a.id,baseId:a.baseId,title:a.title,category:a.category,domain:a.domain,loggedAt:new Date(date.getTime()+j*3600000).toISOString(),duration:a.duration,intensity:a.intensity,impact:assessImpact(a).impact,notes:'',engineVersion:ENGINE_VERSION});}data.checkins.push({date:localDate(date),mood:3+(i%3===0?1:0),energy:3+(i%4===0?1:0),stress:2+(i%3===0?1:0),sleepHours:6.5+(i%4)*.5,waterGlasses:5+(i%4),steps:5500+(i%6)*900,restingHr:'',notes:''});}data.goals.push({id:uid(),title:'Make time to move',domain:'body',target:4});return data;}
function updateImpactPreview(){const a=getActivityById(ui.modal?.id);if(!a)return;const duration=Number($('#log-duration')?.value),intensity=Number($('#log-intensity')?.value);if(!Number.isFinite(duration)||duration<1)return;const out=assessImpact(a,{duration,intensity});const el=$('#impact-preview');if(el){el.textContent=`${out.impact>0?'+':''}${out.impact}`;el.className=`impact-number ${out.impact<0?'negative':''}`;}const caption=$('#log-intensity')?.closest('label');if(caption){caption.firstChild.textContent=`Intensity (${intensity}/10)`;}}
function activityModal(id){const a=getActivityById(id);if(!a){toast('Could not find that activity.');return;}ui.modal={type:'activity',id,duration:a.duration,intensity:a.intensity};render();}
function updateNaturalResults(){const q=$('#natural-input')?.value?.trim()||'',panel=$('#natural-results');if(!panel)return;const found=suggestActivity(q).slice(0,4);panel.innerHTML=q?`<p class="small muted">${found.length?'Suggested matches (choose one to confirm scoring):':'No confident match. Try the catalogue; no score will be invented.'}</p>${found.length?catalogCards(found):`<button class="button ghost small" data-action="natural-to-journal">Save as an unscored reflection ↗</button>`}`:'';}
function handleAction(el){const action=el.dataset.action,id=el.dataset.id;switch(action){
 case 'quick':{const a=ACTIVITIES.find(x=>x.baseId===id);if(a)activityModal(a.id);break;}
 case 'select-activity':activityModal(id);break;
 case 'close-modal':ui.modal=null;render();break;
 case 'rate':{const name=el.dataset.name;const field=el.closest('label.field');field?.querySelectorAll('.rating button').forEach(b=>{b.classList.toggle('selected',b.dataset.value===el.dataset.value);b.setAttribute('aria-pressed',String(b.dataset.value===el.dataset.value))});const hidden=field?.querySelector(`input[name="${name}"]`);if(hidden)hidden.value=el.dataset.value;break;}
 case 'suggest-natural':updateNaturalResults();break;
 case 'natural-to-journal':{const text=$('#natural-input')?.value?.trim();if(!text)return;state.journal.push({id:uid(),text,at:new Date().toISOString()});save();toast('Saved as a private reflection without changing your score.');navigate('journal');break;}
 case 'delete-log':if(confirm('Delete this activity? Its LifeScore impact will also be recalculated.')){state.logs=state.logs.filter(l=>l.id!==id);save();render();toast('Activity deleted and score recalculated.')}break;
 case 'delete-goal':if(confirm('Remove this goal? Your activity history will remain.')){state.goals=state.goals.filter(g=>g.id!==id);save();render();toast('Goal removed.')}break;
 case 'delete-journal':if(confirm('Delete this reflection?')){state.journal=state.journal.filter(j=>j.id!==id);save();render();toast('Reflection deleted.')}break;
 case 'prev-month':ui.viewDate=new Date(ui.viewDate.getFullYear(),ui.viewDate.getMonth()-1,1);render();break;
 case 'next-month':ui.viewDate=new Date(ui.viewDate.getFullYear(),ui.viewDate.getMonth()+1,1);render();break;
 case 'launch-demo':state=demoData();save();navigate('today');toast('Sample data loaded. This is a demo, not your personal record.');break;
 case 'toggle-onboard-goal':{const goal=el.dataset.goal;ui.selectedGoals=ui.selectedGoals.includes(goal)?ui.selectedGoals.filter(x=>x!==goal):[...ui.selectedGoals,goal];el.classList.toggle('selected',ui.selectedGoals.includes(goal));el.setAttribute('aria-pressed',String(ui.selectedGoals.includes(goal)));break;}
 case 'toggle-theme':state.profile.theme=state.profile.theme==='dark'?'light':'dark';save();render();break;
 case 'export-json':download(exportData(state),`vitalab-backup-${today()}.json`,'application/json');toast('Complete backup downloaded.');break;
 case 'export-csv':download(toCSV(state.logs),`vitalab-activities-${today()}.csv`,'text/csv');toast('Activity CSV downloaded.');break;
 case 'print':window.print();break;
 case 'clear-all':if(confirm('Permanently delete ALL VitaLab data saved in this browser? Please export a backup first.')){if(confirm('Final confirmation: delete profile, logs, check-ins, goals and reflections?')){localStorage.removeItem(STORE_KEY);state=emptyState();ui.modal=null;ui.selectedGoals=[];navigate('today');toast('Local VitaLab data deleted.')}}break;
}}
function numberOrEmpty(form,name,min,max){const text=String(form.get(name)||'').trim();if(text==='')return '';const n=Number(text);if(!Number.isFinite(n)||n<min||n>max)throw Error(`${name} must be between ${min} and ${max}`);return n;}
function handleSubmit(e){const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const v=new FormData(f);try{switch(f.id){
 case 'onboard-form':state.profile={name:String(v.get('name')||'').trim().slice(0,70),goals:[...ui.selectedGoals],onboarded:true,theme:state.profile.theme||'dark'};state.demo=false;save();navigate('today');toast('Welcome to VitaLab. Your workspace is ready.');break;
 case 'checkin-form':{const current=state.checkins.find(c=>c.date===today())||{};const obj={...current,date:today(),mood:Number(v.get('mood')||3),energy:Number(v.get('energy')||3),stress:Number(v.get('stress')||current.stress||3),sleepHours:v.has('sleepHours')?numberOrEmpty(v,'sleepHours',0,24):(current.sleepHours??''),waterGlasses:v.has('waterGlasses')?numberOrEmpty(v,'waterGlasses',0,40):(current.waterGlasses??''),steps:v.has('steps')?numberOrEmpty(v,'steps',0,100000):(current.steps??''),restingHr:v.has('restingHr')?numberOrEmpty(v,'restingHr',20,240):(current.restingHr??''),notes:String(v.get('notes')||current.notes||'').slice(0,2000)};if(![obj.mood,obj.energy,obj.stress].every(n=>n>=1&&n<=5))throw Error('Ratings must be from 1 to 5');state.checkins=state.checkins.filter(c=>c.date!==today()).concat(obj);save();render();toast('Daily check-in saved.');break;}
 case 'activity-form':{const a=getActivityById(String(v.get('variant')));if(!a)throw Error('Choose an activity from the library');const duration=Number(v.get('duration')),intensity=Number(v.get('intensity'));if(!Number.isFinite(duration)||duration<1||duration>1440)throw Error('Duration must be 1–1440 minutes');if(!Number.isInteger(intensity)||intensity<1||intensity>10)throw Error('Intensity must be between 1 and 10');const result=assessImpact(a,{duration,intensity});const entry={id:uid(),activityId:a.id,baseId:a.baseId,title:a.title,category:a.category,domain:a.domain,loggedAt:new Date().toISOString(),duration,intensity,impact:result.impact,notes:String(v.get('notes')||'').slice(0,1500),engineVersion:ENGINE_VERSION};state.logs.push(entry);ui.modal=null;save();render();toast(`${a.title} logged (${result.impact>=0?'+':''}${result.impact} estimated points).`);break;}
 case 'goal-form':{const title=String(v.get('title')||'').trim(),domain=String(v.get('domain')||''),target=Number(v.get('target'));if(!title||title.length>90||!DOMAINS.some(d=>d.id===domain)||!Number.isInteger(target)||target<1||target>28)throw Error('Choose a title, dimension and weekly target 1–28');state.goals.push({id:uid(),title,domain,target,createdAt:new Date().toISOString()});save();render();toast('Goal created.');break;}
 case 'journal-form':{const text=String(v.get('text')||'').trim();if(!text||text.length>4000)throw Error('Reflection must be 1–4000 characters');state.journal.push({id:uid(),text,at:new Date().toISOString()});save();render();toast('Private reflection saved.');break;}
 case 'settings-form':state.profile.name=String(v.get('name')||'').slice(0,70);state.profile.theme=v.get('theme')==='light'?'light':'dark';save();render();toast('Preferences saved.');break;
 }}catch(err){toast(err.message||'Could not save. Please check your entries.')}}
function installEvents(){document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const button=e.target.closest('[data-action]');if(button){handleAction(button);return;}if(e.target.id==='modal-backdrop'){ui.modal=null;render();}});document.addEventListener('submit',handleSubmit);document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){ui.query=e.target.value;refreshCatalog()}if(['log-duration','log-intensity'].includes(e.target.id))updateImpactPreview();});document.addEventListener('change',async e=>{if(e.target.id==='catalog-category'){ui.category=e.target.value;refreshCatalog()}if(e.target.id==='activity-variant'){const a=getActivityById(e.target.value);if(!a)return;ui.modal.id=a.id;$('#log-duration').value=a.duration;$('#log-intensity').value=a.intensity;updateImpactPreview()}if(e.target.id==='import-file'){const file=e.target.files?.[0];if(!file)return;try{if(file.size>5_000_000)throw Error('Backup is too large (5 MB maximum)');const parsed=importData(await file.text());if(confirm('Replace all VitaLab data in this browser with the imported backup?')){state=parsed;save();navigate('today');toast('VitaLab backup restored.')}}catch(err){toast(err.message||'Could not import backup.')}finally{e.target.value='';}}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){ui.modal=null;render()} else if(e.key==='Tab'&&ui.modal){const dialog=$('.modal-dialog');const focusable=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled])')];if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});window.addEventListener('hashchange',()=>{const tab=location.hash.slice(2);if(validTabs.has(tab)&&ui.tab!==tab){ui.tab=tab;render();}});}
installEvents();if(validTabs.has(location.hash.slice(2)))ui.tab=location.hash.slice(2);render();if('serviceWorker' in navigator && location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});